CREATE TYPE "EvaluationState" AS ENUM ('queued','evaluated','stale','failed');
CREATE TYPE "EvaluationRecommendation" AS ENUM ('strong_review','review','needs_information','low_match');
CREATE TYPE "CriterionRating" AS ENUM ('strong','meets','partial','missing','contradicted');
CREATE TABLE "candidate_evaluations" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"candidate_id" TEXT NOT NULL REFERENCES "candidates"("id") ON DELETE CASCADE,"position_id" TEXT NOT NULL,"rubric_id" TEXT NOT NULL REFERENCES "evaluation_rubrics"("id"),"rubric_version" INTEGER NOT NULL,"state" "EvaluationState" NOT NULL,"role_fit" INTEGER,"evidence_confidence" INTEGER,"recommendation" "EvaluationRecommendation","evidence_snapshot" JSONB NOT NULL,"provider_execution_id" TEXT,"created_by_id" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "criterion_evaluations" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"candidate_evaluation_id" TEXT NOT NULL REFERENCES "candidate_evaluations"("id") ON DELETE CASCADE,"criterion_id" TEXT NOT NULL REFERENCES "rubric_criteria"("id"),"rating" "CriterionRating" NOT NULL,"score" INTEGER NOT NULL,"evidence_confidence" INTEGER NOT NULL,"reasoning" TEXT NOT NULL,"evidence_claim_ids" JSONB NOT NULL,"gaps" JSONB NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "candidate_evaluations_organization_id_position_id_created_at_idx" ON "candidate_evaluations"("organization_id","position_id","created_at");
CREATE INDEX "candidate_evaluations_organization_id_candidate_id_created_at_idx" ON "candidate_evaluations"("organization_id","candidate_id","created_at");
CREATE INDEX "criterion_evaluations_organization_id_candidate_evaluation_id_idx" ON "criterion_evaluations"("organization_id","candidate_evaluation_id");
